import {readFileSync} from "node:fs";
import type {Page} from "@playwright/test";

// A small, readable source snapshot, generated by the test browser. It is synthetic and contains no remote assets.
export async function evidenceProject(page:Page){
  const sourcePage=await page.context().newPage();
  await sourcePage.setViewportSize({width:600,height:800});
  await sourcePage.setContent(`<meta name="viewport" content="width=device-width,initial-scale=1"><style>body{margin:60px;font:20px Arial;color:#222}h1{font-size:24px}p{margin:30px 0}table{border-collapse:collapse}td,th{border:1px solid #aaa;padding:16px}</style><h1>Site investigation log</h1><p>Borehole BH-01</p><p>Ground level: <span id="ground">10.00</span> m</p><table><tr><th>From</th><th>To</th><th>Description</th></tr><tr><td>0</td><td>2</td><td>Made ground</td></tr><tr><td>2</td><td>12</td><td>Sand</td></tr></table>`);
  const groundBox=await sourcePage.locator("#ground").evaluate(el=>{
    const b=el.getBoundingClientRect();
    return {page:1,x0:b.left/600,y0:b.top/800,x1:b.right/600,y1:b.bottom/800,text:"10.00"};
  });
  const image="data:image/png;base64,"+(await sourcePage.screenshot()).toString("base64");
  await sourcePage.close();
  const project=JSON.parse(readFileSync(new URL("./complete-project.json",import.meta.url),"utf8"));
  const field=(value:string,pageNumber=1)=>({original:value,current:value,boxes:[{page:pageNumber,x0:0.1,y0:0.2,x1:0.6,y1:0.25,text:value}],status:"unreviewed",events:[]});
  project.evidence={version:1,sources:[{id:"source-log",name:"field-log.pdf",pages:[{page:1,width:600,height:800,image},{page:2,width:600,height:800,image}]}],records:[
    {id:"collar-bh1",sourceId:"source-log",method:"pdf-text",fields:{id:field("BH-01"),z:{...field("10"),boxes:[groundBox]},depth:field("12",2)}},
    {id:"layer-fill-bh1",sourceId:"source-log",method:"pdf-text",fields:{boreholeId:field("BH-01"),from:field("0"),to:field("2"),unit:field("fill"),description:field("Made ground")}},
    {id:"layer-sand-bh1",sourceId:"source-log",method:"pdf-text",fields:{boreholeId:field("BH-01"),from:field("2"),to:field("12"),unit:field("sand"),description:field("Sand")}},
    {id:"water-bh1",sourceId:"source-log",method:"pdf-text",fields:{boreholeId:field("BH-01"),depth:field("2"),date:field("2026-01-15")}}
  ]};
  project.boreholes[0].evidenceId="collar-bh1";
  project.boreholes[0].intervals[0].evidenceId="layer-fill-bh1";
  project.boreholes[0].intervals[1].evidenceId="layer-sand-bh1";
  project.boreholes[0].water[0].evidenceId="water-bh1";
  return project;
}
